package campus

import "strings"

const guardConsoleHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Sentinel Campus · Command</title><style>
:root{color-scheme:dark;--ink:#f4f7f6;--muted:#93a09f;--quiet:#667372;--line:#2a3636;--panel:#151d1d;--canvas:#0d1212;--accent:#9ed9bb;--accent-strong:#b8f0d1;--danger:#f1a39a;--amber:#e8c78f;--radius:16px;--shadow:0 22px 70px rgba(0,0,0,.25)}
*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;letter-spacing:.005em}button,select{font:inherit}button{cursor:pointer}.command-shell{min-height:100dvh;display:grid;grid-template-columns:224px minmax(0,1fr)}.rail{border-right:1px solid var(--line);padding:24px 16px;display:flex;flex-direction:column;min-height:100dvh;background:#101616}.brand{display:flex;align-items:center;gap:11px;padding:4px 10px 44px}.brand-mark{width:30px;height:30px;border:1px solid var(--accent);border-radius:9px;display:grid;place-items:center;color:var(--accent);font-size:12px;font-weight:750;letter-spacing:-.08em}.brand-name{font-size:13px;font-weight:760;letter-spacing:.09em;text-transform:uppercase}.brand-sub{font-size:10px;color:var(--quiet);letter-spacing:.12em;text-transform:uppercase;margin-top:1px}.rail-label{font-size:10px;color:var(--quiet);letter-spacing:.16em;text-transform:uppercase;padding:0 11px 10px}.nav{display:grid;gap:4px}.nav a{color:var(--muted);text-decoration:none;padding:10px 11px;border-radius:10px;display:flex;align-items:center;gap:10px}.nav a.active{color:var(--ink);background:#1d2928;box-shadow:inset 2px 0 var(--accent)}.nav a:hover{color:var(--ink);background:#182321}.nav-dot{width:6px;height:6px;border-radius:50%;background:currentColor;opacity:.7}.rail-footer{margin-top:auto;border-top:1px solid var(--line);padding:18px 11px 4px}.local-state{display:flex;align-items:center;gap:8px;color:var(--accent);font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.pulse{width:7px;height:7px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 4px rgba(158,217,187,.1)}.rail-footnote{color:var(--quiet);font-size:11px;margin:8px 0 0}.content{min-width:0;padding:0 42px 44px;max-width:1600px}.topbar{height:80px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.crumb{color:var(--muted);font-size:12px}.crumb strong{color:var(--ink);font-weight:600}.view-chip{border:1px solid var(--line);border-radius:999px;padding:7px 11px;color:var(--muted);font-size:10px;font-weight:750;letter-spacing:.14em;text-transform:uppercase}.hero{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,.8fr);gap:26px;padding:48px 0 40px;border-bottom:1px solid var(--line)}.eyebrow{font-size:10px;color:var(--accent);font-weight:750;letter-spacing:.18em;text-transform:uppercase}.hero h1{font-size:clamp(38px,5vw,68px);line-height:.98;letter-spacing:-.065em;max-width:680px;margin:15px 0 17px;font-weight:680}.hero-copy{max-width:520px;color:var(--muted);font-size:16px}.hero-metrics{display:flex;gap:30px;margin-top:30px}.metric{display:grid;gap:2px}.metric strong{font-size:27px;letter-spacing:-.05em;font-weight:650}.metric span{color:var(--quiet);font-size:10px;letter-spacing:.13em;text-transform:uppercase}.brief{align-self:end;border-left:1px solid var(--line);padding:5px 0 4px 28px}.brief-kicker{color:var(--quiet);font-size:10px;letter-spacing:.16em;text-transform:uppercase}.brief-status{display:flex;align-items:center;gap:9px;margin:12px 0 17px;color:var(--accent-strong);font-size:19px;font-weight:700;letter-spacing:-.02em}.brief-row{display:flex;justify-content:space-between;padding:9px 0;border-top:1px solid var(--line);color:var(--muted);font-size:12px}.brief-row strong{color:var(--ink);font-weight:600}.section-head{display:flex;align-items:end;justify-content:space-between;padding:32px 0 15px}.section-head h2{font-size:18px;letter-spacing:-.02em;margin:0;font-weight:650}.section-meta{color:var(--quiet);font-size:11px}.gate-overview{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.gate-card{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:20px;min-height:290px;display:flex;flex-direction:column;box-shadow:var(--shadow);transition:border-color .2s ease,transform .2s ease}.gate-card:hover{border-color:#445654;transform:translateY(-2px)}.gate-card[data-mode="AUTO"]{border-color:#4d7460}.gate-top{display:flex;justify-content:space-between;align-items:start}.gate-number{color:var(--quiet);font:11px/1.2 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.12em}.gate-card h3{font-size:21px;letter-spacing:-.035em;margin:8px 0 0;font-weight:650}.mode{padding:6px 9px;border-radius:999px;background:#24322f;color:var(--accent);font-size:10px;font-weight:750;letter-spacing:.14em}.mode.shadow{color:var(--amber);background:#332f24}.mode.manual{color:var(--danger);background:#342624}.controller{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:11px;margin-top:9px}.controller .pulse{width:5px;height:5px}.decision-box{margin:24px 0 20px;padding:15px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.decision-label{color:var(--quiet);font-size:10px;text-transform:uppercase;letter-spacing:.15em}.decision-value{font-size:25px;font-weight:680;letter-spacing:-.04em;margin-top:4px}.decision-sub{color:var(--muted);font-size:12px;margin-top:2px}.gate-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:auto}.button{border:1px solid var(--line);border-radius:9px;color:var(--ink);background:#202b2a;padding:9px 11px;font-size:11px;font-weight:650;transition:background .2s ease,transform .15s ease}.button:hover{background:#2b3a37}.button:active{transform:translateY(1px)}.button.primary{background:var(--accent);color:#0e1714;border-color:var(--accent)}.button.primary:hover{background:var(--accent-strong)}.mode-select{min-width:110px;background:#111918;color:var(--muted);border:1px solid var(--line);border-radius:9px;padding:8px 8px;font-size:11px}.activity{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:14px;margin-top:14px}.ledger,.aside-panel{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}.ledger-head,.aside-head{padding:16px 18px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.ledger-head strong,.aside-head strong{font-size:12px;font-weight:650}.ledger-head span,.aside-head span{color:var(--quiet);font-size:10px;text-transform:uppercase;letter-spacing:.14em}.event-row{display:grid;grid-template-columns:86px 1fr 110px 100px 48px;gap:10px;align-items:center;padding:13px 18px;border-bottom:1px solid rgba(42,54,54,.7);font-size:12px}.event-row:last-child{border-bottom:0}.event-time,.event-reason{color:var(--muted)}.event-gate{color:var(--ink);font-weight:600}.event-plate{font:12px ui-monospace,SFMono-Regular,Menlo,monospace;color:#c9d5d1}.event-kind{font-size:10px;letter-spacing:.1em;font-weight:800}.event-kind.open{color:var(--accent)}.event-kind.deny_alert{color:var(--danger)}.event-kind.no_action,.event-kind.hold_guard{color:var(--amber)}.event-pulse{color:var(--accent);text-align:right;font-size:10px;font-weight:800}.empty{padding:30px 18px;color:var(--quiet);font-size:12px}.aside-body{padding:18px}.aside-stat{display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid var(--line);font-size:12px;color:var(--muted)}.aside-stat:last-child{border-bottom:0}.aside-stat strong{color:var(--ink);font-weight:650}.footer-note{padding:28px 0 0;color:var(--quiet);font-size:11px;display:flex;justify-content:space-between}.footer-note span:last-child{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}@media(max-width:1000px){.command-shell{grid-template-columns:72px minmax(0,1fr)}.rail{padding:18px 10px}.brand{padding:4px 5px 38px}.brand-name,.brand-sub,.rail-label,.nav a span,.rail-footnote{display:none}.brand{justify-content:center}.nav a{justify-content:center}.content{padding:0 24px 34px}.hero{grid-template-columns:1fr}.brief{border-left:0;border-top:1px solid var(--line);padding:20px 0 0}.activity{grid-template-columns:1fr}}@media(max-width:720px){.command-shell{display:block}.rail{min-height:auto;height:62px;border-right:0;border-bottom:1px solid var(--line);display:block;padding:0 16px}.brand{display:flex;justify-content:start;height:62px;padding:0}.brand-name,.brand-sub{display:block}.nav,.rail-footer{display:none}.content{padding:0 16px 28px}.topbar{height:64px}.hero{padding:34px 0 30px}.hero h1{font-size:43px}.hero-metrics{gap:20px}.gate-overview{grid-template-columns:1fr}.gate-card{min-height:260px}.event-row{grid-template-columns:68px 1fr 75px;gap:8px}.event-reason,.event-pulse{display:none}.footer-note{display:block}.footer-note span{display:block;margin-top:5px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
</style></head><body><div class="command-shell"><aside class="rail"><div class="brand"><div class="brand-mark">SC</div><div><div class="brand-name">Sentinel</div><div class="brand-sub">Campus command</div></div></div><div class="rail-label">Workspace</div><nav class="nav"><a class="active" href="#overview"><i class="nav-dot"></i><span>Overview</span></a><a href="#gates"><i class="nav-dot"></i><span>Gate control</span></a><a href="#activity"><i class="nav-dot"></i><span>Activity</span></a></nav><div class="rail-footer"><div class="local-state"><i class="pulse"></i>Local</div><p class="rail-footnote">No cloud connection<br>Simulator hardware</p></div></aside><main class="content"><header class="topbar"><div class="crumb">NFSU / <strong>Gandhinagar / North Campus</strong></div><div class="view-chip">VC VIEW · LOCAL</div></header><section class="hero" id="overview"><div><div class="eyebrow">Campus access control</div><h1>Campus access,<br>under control.</h1><p class="hero-copy">A clear operational view of arrivals, gate health, and every decision made at the campus perimeter.</p><div class="hero-metrics"><div class="metric"><strong>03</strong><span>Configured gates</span></div><div class="metric"><strong id="metric-open">00</strong><span>Open alerts</span></div><div class="metric"><strong id="metric-events">00</strong><span>Logged events</span></div></div></div><div class="brief"><div class="brief-kicker">Campus status</div><div class="brief-status"><i class="pulse"></i>Operational</div><div class="brief-row"><span>Decision path</span><strong>Local only</strong></div><div class="brief-row"><span>Hardware</span><strong>Simulator online</strong></div><div class="brief-row"><span>Last refresh</span><strong id="refresh-time">--:--</strong></div></div></section><div class="section-head" id="gates"><h2>Gate overview</h2><span class="section-meta">Three independent access points</span></div><section class="gate-overview" id="gate-cards"></section><section class="activity" id="activity"><div class="ledger"><div class="ledger-head"><strong>Recent activity</strong><span>Last 20 events</span></div><div id="events"></div></div><aside class="aside-panel"><div class="aside-head"><strong>Operating posture</strong><span>Today</span></div><div class="aside-body"><div class="aside-stat"><span>Default mode</span><strong>SHADOW</strong></div><div class="aside-stat"><span>Auto-open rule</span><strong>Exact match</strong></div><div class="aside-stat"><span>Lockout interval</span><strong>10 seconds</strong></div><div class="aside-stat"><span>Data location</span><strong>On device</strong></div></div></aside></section><div class="footer-note"><span>Sentinel Campus · NFSU Gandhinagar</span><span>v0.1 · local demonstration</span></div></main></div><script>
const authToken='__TOKEN__';
const esc=function(value){return String(value==null?'':value).replace(/[&<>'"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]})};
async function state(){const r=await fetch('/api/state');if(!r.ok)throw new Error('State unavailable');return r.json()}
async function act(url,body){const r=await fetch(url,{method:'POST',headers:{'content-type':'application/json','X-Sentinel-Token':authToken},body:JSON.stringify(body)});if(!r.ok){alert(await r.text())}await render()}
function modeClass(mode){return mode==='AUTO'?'':(mode==='MANUAL'?'manual':'shadow')}
function decisionLabel(mode){return mode==='AUTO'?'Awaiting read':'Shadow monitoring'}
function read(g){act('/api/gates/'+encodeURIComponent(g)+'/read',{plate_norm:'GJ01AB1234',confidence:.99,frames:3})}function unknown(g){act('/api/gates/'+encodeURIComponent(g)+'/read',{plate_norm:'GJ01ZZ9999',confidence:.99,frames:3})}function mode(g,m){if(m!=='Change mode...'&&confirm('Confirm mode change to '+m+'?'))act('/api/gates/'+encodeURIComponent(g)+'/mode',{mode:m,confirm:true})}function override(g,action){act('/api/gates/'+encodeURIComponent(g)+'/override',{action:action,reason:'guard console override',confirm:true})}
function renderGate(g){return '<article class="gate-card" data-mode="'+esc(g.mode)+'"><div class="gate-top"><div><div class="gate-number">'+esc(g.id.toUpperCase())+'</div><h3>'+esc(g.name)+'</h3><div class="controller"><i class="pulse"></i>Controller online · simulator</div></div><span class="mode '+modeClass(g.mode)+'">'+esc(g.mode)+'</span></div><div class="decision-box"><div class="decision-label">Current posture</div><div class="decision-value">'+decisionLabel(g.mode)+'</div><div class="decision-sub">No active access decision</div></div><div class="gate-actions"><button class="button primary" onclick="read(\''+esc(g.id)+'\')">Test authorised</button><button class="button" onclick="unknown(\''+esc(g.id)+'\')">Test unknown</button><button class="button" onclick="override(\''+esc(g.id)+'\',\'OPEN\')">Open once</button><select class="mode-select" onchange="mode(\''+esc(g.id)+'\',this.value)" aria-label="Change mode for '+esc(g.name)+'"><option>Change mode...</option><option>SHADOW</option><option>AUTO</option><option>MANUAL</option></select></div></article>'}
function renderEvent(e){const kind=String(e.decision||'').toLowerCase();return '<div class="event-row"><span class="event-time">'+esc(new Date(e.timestamp).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}))+'</span><span class="event-gate">'+esc(e.gate_id)+'</span><span class="event-plate">'+esc(e.plate_norm||'—')+'</span><span class="event-kind '+esc(kind)+'">'+esc(e.decision)+'</span><span class="event-pulse">'+(e.relay_pulsed?'PULSE':'')+'</span></div>'}
async function render(){try{const s=await state();document.querySelector('#gate-cards').innerHTML=s.gates.map(renderGate).join('');const events=(s.events||[]).slice().reverse();document.querySelector('#events').innerHTML=events.length?events.map(renderEvent).join(''):'<div class="empty">No events yet. The console is ready for the first supervised read.</div>';document.querySelector('#metric-events').textContent=String(events.length).padStart(2,'0');document.querySelector('#refresh-time').textContent=new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});document.querySelector('#metric-open').textContent='00'}catch(error){document.querySelector('#events').innerHTML='<div class="empty">Unable to reach the local decision service.</div>'}}
render();setInterval(render,3000)
</script></body></html>`

func renderGuardConsole(token string) string {
	return strings.ReplaceAll(guardConsoleHTML, "__TOKEN__", token)
}
